messages.content:
Tool response:
Tool: search_products
Description: Search Products
Parameters:
    {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "Search term to match against product names",
          "title": "Query"
        },
        "min_rating": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum average rating (default: 4.5)",
          "default": 4.5,
          "title": "Min Rating"
        },
        "prime_only": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Whether to filter for Prime eligible items only (default: true)",
          "default": true,
          "title": "Prime Only"
        },
        "limit": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum number of results to return (default: 3)",
          "default": 3,
          "title": "Limit"
        }
      },
      "required": [
        "query"
      ]
    }
